with a as(select * from public.authors where open_library_id=any(array['OL2829179A']::text[])),w as(select * from public.works where open_library_id=any(array['OL20094468W']::text[])) select jsonb_build_object('checked_at',clock_timestamp(),'project','hlvujbrmfdlrfxdjwsmb','authors',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from a t),'author_corpora',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.works t where author_id in(select id from a)),'works',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from w t),'editions',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.editions t where work_id in(select id from w) or isbn_13=any(array['9781405936002','9789049807368']::text[]) or open_library_edition_id=any(array['OL42859963M','OL42371583M']::text[])),'reserved_range',jsonb_build_object('works',(select count(*) from public.works where id between 987121001 and 987121999),'editions',(select count(*) from public.editions where id between 987221001 and 987221999),'authors',(select count(*) from public.authors where id between 987321001 and 987321999))) as preflight;
